def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_towards(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def first_pos(seq):
        if not seq:
            return None
        for item in seq:
            p = pos(item, None)
            if p is not None:
                return p
        return None

    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_p = (sx, sy)
    opp_p = (ox, oy)

    env = observation.get("environment_name", "resource_collection")
    role = observation.get("self_role", "")

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_towards(self_p, opp_p)
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        best = None
        best_d = None
        for c in corners:
            d = manhattan(c, opp_p)
            if best is None or d > best_d:
                best, best_d = c, d
        return step_towards(self_p, best if best is not None else (0, 0))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        t = first_pos(targets)
        if t is None:
            return step_away(self_p, opp_p)
        return step_towards(self_p, t)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    t = first_pos(resources)
    if t is not None:
        return step_towards(self_p, t)

    # Fallbacks for unknown or sparse observations
    danger = observation.get("danger_positions") or observation.get("opponents") or []
    dpos = first_pos(danger)
    if dpos is not None:
        return step_away(self_p, dpos)

    return step_towards(self_p, opp_p)

